# /// script
# requires-python = ">=3.12"
# dependencies = []
# ///
"""Check valid controls and reject corrupt results before accepting agent scores."""
import copy
import json
from pathlib import Path

from grade import check
from reference import coating_reflection, derivative, sphere_efficiency


def main():
    tasks=json.loads((Path(__file__).resolve().parents[2]/'benchmarks/agent-api/reference.json').read_text())
    for task in tasks:
        for config,expected in zip(task['inputs'],task['expected'],strict=True):
            output=copy.deepcopy(expected)
            if task['category']=='optimization':
                if task['id']=='radius_inverse_design':
                    # Recover this synthetic control from the original hidden-data construction.
                    radius=.11 if config['initial_radius']==.075 else .105
                    def objective(r):
                        q=[sphere_efficiency(r,config['epsilon'],w,config['lmax']) for w in config['wavelengths']]
                        return sum(((a-b)/b)**2 for a,b in zip(q,config['target_efficiencies'],strict=True))/len(q)
                    output={'radius':radius,'loss':objective(radius),'initial_loss':expected['initial_loss'],'gradient':derivative(objective,radius),'fitted_efficiencies':config['target_efficiencies'],'loss_history':[expected['initial_loss'],objective(radius)]}
                else:
                    thickness=task['id']=='antireflection_design';key='thickness' if thickness else 'wavelength'
                    x=expected['optimum']
                    def objective(value):
                        return coating_reflection(value if thickness else config['thickness'],config['wavelength'] if thickness else value,config['epsilon'],config['substrate_epsilon'])
                    output={key:x,'reflection':objective(x),'initial_reflection':expected['initial_reflection'],'gradient':derivative(objective,x),'loss_history':[expected['initial_reflection'],objective(x)]}
            check(task,config,expected,output,{'SphereContext':2})
            bad=copy.deepcopy(output)
            key=next(iter(expected)) if task['category']!='optimization' else ('loss' if task['id']=='radius_inverse_design' else 'reflection')
            bad[key]=12345.0
            try:check(task,config,expected,bad,{'SphereContext':2})
            except AssertionError:pass
            else:raise AssertionError(task['id']+' accepted a corrupt result')
            if task['category']!='forward':
                try:check(task,config,expected,output,{})
                except AssertionError:pass
                else:raise AssertionError(task['id']+' accepted missing native pullbacks')
            if task['id'] in ('coated_sphere','cylinder_width','dimer_field'):
                alias={k+'_cross_section' if k in ('scattering','extinction','absorption') else k:v for k,v in output.items()}
                check(task,config,expected,alias,{})
    print('PASS: 26 independent controls; corrupted outputs and missing native gradients rejected; equivalent quantity names accepted.')


if __name__=='__main__':main()
